try {
  const response = $input.first().json || {};
  const records = response.records || response.list || (Array.isArray(response) ? response : []);

  const parseIfString = (val) => {
    if (typeof val === 'string') {
      try {
        const parsed = JSON.parse(val);
        return (parsed && typeof parsed === 'object') ? parsed : {};
      } catch {
        return {};
      }
    }
    return (val && typeof val === 'object') ? val : {};
  };

  const initData = parseIfString($('Initialisation standardisée').first()?.json);
  const webhookRaw = parseIfString($('Webhook Délivrance').first()?.json);
  const webhookBody = parseIfString(webhookRaw.body || webhookRaw);
  const initMission = parseIfString(initData.mission);
  const initMissionBody = parseIfString(initMission.body || initMission);
  const canonicalPayload = parseIfString(
    webhookBody.canonical_payload || initMissionBody.canonical_payload || initData.canonical_payload
  );

  const mission = {
    ...canonicalPayload,
    ...webhookBody,
    ...parseIfString(initData.body),
    ...initMission,
    ...initMissionBody
  };

  // Recherche directe puis extraction récursive (y compris dans les chaînes JSON ou textes)
  let targetRef = String(
    mission.reference_mission ||
    mission.mission_ref ||
    mission.Mission_Ref ||
    mission.reference ||
    mission.Code_Mission ||
    mission.code_mission ||
    mission.ref ||
    ''
  ).trim();

  if (!/^MIS-\d{4}-\d+$/i.test(targetRef)) {
    const findMissionCode = (obj, depth = 0) => {
      if (obj === null || obj === undefined || depth > 6) return '';
      if (typeof obj === 'string') {
        const match = obj.match(/\bMIS-\d{4}-\d+\b/i);
        return match ? match[0].toUpperCase() : '';
      }
      if (typeof obj === 'object') {
        for (const val of Object.values(obj)) {
          const found = findMissionCode(val, depth + 1);
          if (found) return found;
        }
      }
      return '';
    };
    targetRef = findMissionCode({ mission, initData, webhookRaw });
  } else {
    targetRef = targetRef.toUpperCase();
  }

  if (records.length === 0) {
    throw new Error(
      `NocoDB a renvoyé 0 enregistrement pour la référence '${targetRef || 'non trouvée'}'. Vérifiez le filtre 'where' (sans apostrophes) et la table mv1cb6xm00g6rf5 dans 'Rechercher mission à délivrer'.`
    );
  }

  let row = null;
  if (targetRef) {
    row = records.find((candidate) => {
      const f = candidate.fields || candidate;
      const candidateRef =
        f.Mission_Ref ||
        f.Code_Mission ||
        f.Reference_Mission ||
        f.reference_mission ||
        f.Title ||
        '';
      return String(candidateRef).trim().toUpperCase() === targetRef;
    });
  } else if (records.length === 1) {
    row = records[0];
  }

  if (!row) {
    throw new Error(`Mission (${targetRef || 'sans référence'}) absente des ${records.length} lignes retournées par NocoDB.`);
  }

  const f = row.fields || row;
  const resolvedRef = String(
    targetRef ||
    f.Mission_Ref ||
    f.Code_Mission ||
    f.Reference_Mission ||
    f.reference_mission ||
    f.Title ||
    ''
  ).trim().toUpperCase();

  const recordId = row.id || row.id_fields?.Id || f.Id || f.id;
  if (!Number.isSafeInteger(Number(recordId))) {
    throw new Error('ID numérique NocoDB manquant ou invalide.');
  }

  const amountValue = mission.montant_eur ?? mission.montant ?? mission.amount ?? f.Montant ?? f.Montant_FCFA ?? 0;
  const amount = Number(amountValue);
  if (!Number.isFinite(amount) || amount < 0) {
    throw new Error('Montant de séquestre manquant ou invalide.');
  }

  const rawPhone =
    mission.whatsapp ||
    mission.telephone ||
    mission.phone ||
    f.WhatsApp ||
    f.Telephone ||
    '';
  const phone = String(rawPhone).replace(/\D/g, '');
  if (!/^\d{8,15}$/.test(phone)) {
    throw new Error('Numéro WhatsApp/téléphone au format chiffres seuls (8 à 15 chiffres) manquant ou invalide.');
  }

  const webViewLink =
    mission.webViewLink ||
    mission.pdf_url ||
    mission.tracker_url ||
    f.Rapport_URL ||
    `https://e-metalabs.com/tracker.html?ref=${encodeURIComponent(resolvedRef)}`;

  const sha256Hash = String(
    mission.empreinte_sha256 ||
    mission.sha256_hash ||
    mission.hash ||
    f.Empreinte_SHA256 ||
    f.Contrat_Hash_Ref ||
    ''
  ).trim();

  // Adaptez 'Livre_Client' si votre option Single select dans Statut_Mandat porte un autre nom exact
  const patchFields = {
    Statut_Mandat: 'Livre_Client'
  };
  if (sha256Hash) {
    patchFields.Empreinte_SHA256 = sha256Hash;
  }

  return [
    {
      json: {
        ...mission,
        reference: resolvedRef,
        reference_mission: resolvedRef,
        telephone: phone,
        whatsapp: phone,
        record_id: Number(recordId),
        sha256_hash: sha256Hash,
        empreinte_sha256: sha256Hash,
        patch: {
          id: Number(recordId),
          fields: patchFields
        },
        escrow: {
          devise: mission.devise || mission.currency || f.Devise || 'EUR',
          montant_total: amount,
          part_cabinet: Math.round(amount * 0.15 * 100) / 100,
          part_expert: Math.round(amount * 0.85 * 100) / 100,
          expert_release_at: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString()
        },
        webViewLink
      }
    }
  ];
} catch (err) {
  throw new Error(`Mapping délivrance impossible: ${err.message}`);
}

const input = $input.first().json;
const pdfBase64 = String(input.pdf_base64 || '').trim();
if (!pdfBase64) {
  throw new Error('Le contenu PDF encodé en base64 est manquant.');
}
const ref = String(input.reference_mission || input.reference || input.mission_ref || 'rapport').trim();
const token16 = Array.from({ length: 16 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const fileName = `${ref}-${token16}.pdf`;
const rapportUrl = `https://rapports.e-metalabs.com/${fileName}`;
const binaryData = await this.helpers.prepareBinaryData(Buffer.from(pdfBase64, 'base64'), fileName, 'application/pdf');
const patch = {
  ...input.patch,
  fields: {
    ...input.patch?.fields,
    Rapport_URL: rapportUrl
  }
};
return [{
  json: {
    ...input,
    rapport_file_path: `/home/node/.n8n-files/rapports/${fileName}`,
    rapport_url: rapportUrl,
    webViewLink: rapportUrl,
    patch
  },
  binary: { pdf_file: binaryData }
}];

